import React from 'react';
import {useFocusMode} from '../../context/focusMode';

const DRAWIO_HTML_BASE64 = '';
const DIAGRAM_ASPECT_RATIO = 1.64;
const DEFAULT_MIN_HEIGHT = 420;
const FOCUS_MIN_HEIGHT = 520;
const MAX_HEIGHT = 980;

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

export default function DrawioArchitectureEmbed() {
  const {isFocusMode} = useFocusMode();
  const containerRef = React.useRef(null);
  const [height, setHeight] = React.useState(620);
  const diagramDataUrl = React.useMemo(() => `data:text/html;base64,${DRAWIO_HTML_BASE64}`, []);

  const recalculateHeight = React.useCallback(() => {
    if (typeof window === 'undefined') {
      return;
    }

    const container = containerRef.current;
    if (!container) {
      return;
    }

    const width = container.clientWidth || 0;
    if (!width) {
      return;
    }

    const preferredHeight = width / DIAGRAM_ASPECT_RATIO;
    const viewportCap = window.innerHeight * (isFocusMode ? 0.9 : 0.78);
    const minHeight = isFocusMode ? FOCUS_MIN_HEIGHT : DEFAULT_MIN_HEIGHT;
    const nextHeight = Math.round(clamp(preferredHeight, minHeight, Math.min(MAX_HEIGHT, viewportCap)));

    setHeight((current) => (current === nextHeight ? current : nextHeight));
  }, [isFocusMode]);

  React.useEffect(() => {
    recalculateHeight();
  }, [recalculateHeight]);

  React.useEffect(() => {
    if (typeof window === 'undefined') {
      return undefined;
    }

    const onWindowResize = () => {
      recalculateHeight();
    };

    window.addEventListener('resize', onWindowResize);

    if (typeof ResizeObserver === 'undefined') {
      return () => {
        window.removeEventListener('resize', onWindowResize);
      };
    }

    const observer = new ResizeObserver(() => {
      recalculateHeight();
    });

    const container = containerRef.current;
    if (container) {
      observer.observe(container);
    }

    return () => {
      observer.disconnect();
      window.removeEventListener('resize', onWindowResize);
    };
  }, [recalculateHeight]);

  return (
    <figure style={{margin: 0}}>
      <div
        ref={containerRef}
        style={{
          position: 'relative',
          width: '100%',
          height: `${height}px`,
          transition: 'height 180ms ease',
          border: '1px solid var(--ifm-toc-border-color)',
          borderRadius: '8px',
          overflow: 'hidden',
        }}
      >
        <iframe
          src={diagramDataUrl}
          title="OpenLM Platform high-level architecture diagram"
          frameBorder="0"
          loading="lazy"
          style={{width: '100%', height: '100%', border: 0}}
        />
      </div>
    </figure>
  );
}
